import { useState, useEffect, useCallback, useMemo, useRef } from "react";
import { cellAllowsMapExit } from "./editor-map-model.js";
import { cellIsOpenDoorTile, mergeOpenedDoorsAfterStep } from "./dungeon-melee-doorway.js";
import { moveCurrentHeroInSession } from "./dungeon-script-runtime.js";
import { truncateHeroPathForMonsterObstacles } from "./dungeon-hero-path-monsters.js";

export function useTurnLogic({
  gameSession,
  visibilityMap,
  onNotify,
  trapsLogic,
  heroStatsLogic,
  hooksPathfinding,
  combatLogic,
  mapInteractionLogic,
  visibilityCalc,
  sessionManager
}) {
  const [turnPhase, setTurnPhase] = useState({ HasMoved: false, HasPerformedAction: false, IsTurnFinished: false });
  const [movementPoints, setMovementPoints] = useState(null);
  const [hoveredPath, setHoveredPath] = useState([]);
  const [hoveredPathVariant, setHoveredPathVariant] = useState(null);
  const [canAttack, setCanAttack] = useState(false);
  const [attacksPerformed, setAttacksPerformed] = useState(0);
  const [isMoving, setIsMoving] = useState(false);
  const [isMovingStarted, setIsMovingStarted] = useState(false);
  const [canOpenDoor, setCanOpenDoor] = useState(null);
  const [activePath, setActivePath] = useState([]);

  const previousActiveTurnKey = useRef(null);
  const objectiveNotifyMissionKeyRef = useRef(null);
  const previousObjectiveCompletedRef = useRef(false);
  /** Ritirata: conferma già data prima di entrare sulla cella scale (evita doppio dialog e loop). */
  const pendingStairsExitConfirmedRef = useRef(false);

  // -----------------------------------------------------------------------
  // Watchdog: mantiene `canOpenDoor` SEMPRE sincronizzato con la posizione
  // dell'eroe attivo e con `openedDoors`. È un safety net rispetto alle
  // chiamate sparse a `setCanOpenDoor` lungo il file: molte di esse usano
  // `gameSession` da closure stale (calcolato prima del commit della
  // posizione), il che causava il bug "sono sopra una porta ma non vedo
  // il pulsante 'Apri porta'". Questa useEffect ricalcola il valore ad
  // ogni cambio di posizione/heroes/openedDoors usando lo state aggiornato.
  // -----------------------------------------------------------------------
  const activeHero = useMemo(() => {
    if (!Array.isArray(gameSession?.heroes)) return null;
    return gameSession.heroes.find(h => h.turnOrder === gameSession?.currentTurn) || null;
  }, [gameSession?.heroes, gameSession?.currentTurn]);

  const activeHeroPosKey = activeHero ? `${activeHero.x},${activeHero.y}` : null;
  const openedDoorsKey = useMemo(
    () => Array.isArray(gameSession?.openedDoors) ? gameSession.openedDoors.join("|") : "",
    [gameSession?.openedDoors]
  );

  useEffect(() => {
    if (!activeHero) {
      setCanOpenDoor(null);
      return;
    }
    // Durante il movimento attivo evitiamo aggiornamenti per non far
    // "lampeggiare" il pulsante mentre l'eroe attraversa una porta.
    if (isMoving) return;
    const next = mapInteractionLogic?.isFrontOfDoor?.(activeHero.x, activeHero.y, null) || null;
    setCanOpenDoor(next);
    // Dipendiamo solo dai dati osservabili: posizione eroe, openedDoors, eroe-id,
    // moving flag, e l'oggetto mapInteractionLogic (che incorpora porte/passaggi).
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeHero?.heroId, activeHeroPosKey, openedDoorsKey, isMoving, mapInteractionLogic]);

  const checkMissionObjective = useCallback(() => {
    const header = gameSession?.currentMap?.header;
    const currentMap = gameSession?.currentMap;
    if (!header || !currentMap) return true;

    // Per i mostri id 0 è valido (Goblin), quindi il sentinel "nessun obiettivo" è -1.
    // Per oggetti/armi invece id 0 è la voce vuota in items.json/equipment.json: si tiene `> 0`.
    const bossObjectiveId = header.mostro_uscita >= 0 ? header.mostro_uscita : null;
    const itemObjectiveId = header.oggetto_f > 0 ? header.oggetto_f : null;
    const weaponObjectiveId = header.arma_f > 0 ? header.arma_f : null;
    const treasureTarget = header.tesoro_finale;
    const hasTreasureObjective = treasureTarget && (treasureTarget.x !== 0 || treasureTarget.y !== 0);

    // Nessun obiettivo nel header (boss/tesoro/oggetto/arma): la riuscita è "trovare l'uscita".
    // L'uscita dalle scale completa la missione; non serve altro obiettivo in editor o in gioco.
    if (bossObjectiveId == null && !itemObjectiveId && !weaponObjectiveId && !hasTreasureObjective) {
      return true;
    }

    if (bossObjectiveId != null) {
      const bossAlive = gameSession.monsters?.some(m => m.monster?.id === bossObjectiveId);
      const bossHiddenButUnspawned = currentMap.grid?.some(c => c.mostab?.mos && c.mostab?.mosid === bossObjectiveId && !gameSession.spawnedLocations?.includes(`${c.x},${c.y}`));
      if (bossAlive || bossHiddenButUnspawned) return false;
    }

    if (hasTreasureObjective) {
      const targetCell = currentMap.grid?.find(c => c.x === treasureTarget.x && c.y === treasureTarget.y);
      if (targetCell && (targetCell.tes?.mon > 0 || targetCell.tes?.ogg > 0 || targetCell.tes?.arma > 0 || targetCell.tes?.trp > 0)) {
        return false;
      }
    }

    if (itemObjectiveId) {
      const itemStillOnMap = currentMap.grid?.some(c => c.tes?.ogg === itemObjectiveId);
      const itemOwned = gameSession.heroes?.some(h => h.inventory?.includes(itemObjectiveId));
      if (itemStillOnMap || !itemOwned) return false;
    }

    if (weaponObjectiveId) {
      const weaponStillOnMap = currentMap.grid?.some(c => c.tes?.arma === weaponObjectiveId);
      const weaponOwned = gameSession.heroes?.some(h => h.equipment?.includes(weaponObjectiveId));
      if (weaponStillOnMap || !weaponOwned) return false;
    }

    return true;
  }, [gameSession]);

  const isMissionObjectiveCompleted = useMemo(() => checkMissionObjective(), [checkMissionObjective]);
  const missionKey = `${gameSession?.campaignName ?? ""}|${gameSession?.currentMissionIndex ?? "null"}`;
  const hasMissionObjectiveConfigured = useMemo(() => {
    const header = gameSession?.currentMap?.header;
    if (!header) return false;
    const bossObjectiveId = header.mostro_uscita >= 0 ? header.mostro_uscita : null;
    const itemObjectiveId = header.oggetto_f > 0 ? header.oggetto_f : null;
    const weaponObjectiveId = header.arma_f > 0 ? header.arma_f : null;
    const t = header.tesoro_finale;
    const hasTreasureObjective = !!(t && (t.x !== 0 || t.y !== 0));
    return bossObjectiveId != null || !!itemObjectiveId || !!weaponObjectiveId || hasTreasureObjective;
  }, [gameSession?.currentMap?.header]);

  useEffect(() => {
    if (objectiveNotifyMissionKeyRef.current !== missionKey) {
      objectiveNotifyMissionKeyRef.current = missionKey;
      previousObjectiveCompletedRef.current = isMissionObjectiveCompleted;
      return;
    }
    const justCompleted = previousObjectiveCompletedRef.current === false && isMissionObjectiveCompleted === true;
    if (justCompleted && hasMissionObjectiveConfigured) {
      onNotify("Obiettivo missione completato! Raggiungi le scale per uscire.");
    }
    previousObjectiveCompletedRef.current = isMissionObjectiveCompleted;
  }, [missionKey, isMissionObjectiveCompleted, hasMissionObjectiveConfigured, onNotify]);

  const canMeleeAcrossCells = useCallback((fromX, fromY, toX, toY) => {
    const fromCell = visibilityMap?.data?.find(c => c.x === fromX && c.y === fromY);
    const toCell = visibilityMap?.data?.find(c => c.x === toX && c.y === toY);
    if (!fromCell || !toCell) return true;
    if (fromCell.valo === toCell.valo) return true;

    return (
      cellIsOpenDoorTile(gameSession, fromX, fromY) ||
      cellIsOpenDoorTile(gameSession, toX, toY)
    );
  }, [visibilityMap, gameSession]);


  const endTurn = useCallback((force = false) => {
    if (isMoving && !force) return;

    const currentHero = gameSession?.heroes?.find(h => h.turnOrder === gameSession.currentTurn);
    if (currentHero) {
      if (currentHero.activeStatus?.includes("InvisiblePassage")) {
        onNotify("L'effetto di Passaggio Invisibile svanisce.");
      }
      if (currentHero.activeStatus?.includes("FoggyMist")) {
        onNotify("L'effetto di Nebbia Caliginosa svanisce.");
      }
    }

    let nextTurn = gameSession?.currentTurn || 1;
    let nextHero = null;
    const participatingHeroes =
      gameSession?.heroes?.filter((h) => (h.turnOrder ?? 0) > 0) ?? [];
    const maxTurn =
      participatingHeroes.length > 0
        ? participatingHeroes.length
        : gameSession?.heroes?.length || 0;

    for (let i = 0; i < maxTurn; i++) {
      nextTurn++;
      nextHero = gameSession?.heroes?.find(h => h.turnOrder === nextTurn);
      if (nextHero && nextHero.currentBody > 0 && !nextHero.isEscaped) {
        break;
      }
    }

    setTurnPhase({ HasMoved: false, HasPerformedAction: false, IsTurnFinished: false });
    setMovementPoints(null);
    setActivePath([]);
    setHoveredPath([]);
    setHoveredPathVariant(null);
    setIsMoving(false);
    setIsMovingStarted(false);
    setAttacksPerformed(0);

    if (nextHero) {
      setCanOpenDoor(mapInteractionLogic?.isFrontOfDoor?.(nextHero.x, nextHero.y, null) || null);
    }

    if (currentHero) {
      if ((currentHero.bonusMeleeAttackQuota || 0) > 0) {
        sessionManager.clearBonusMeleeAttackQuotaForHero(currentHero.heroId);
      }
      if (currentHero.activeStatus?.includes("FoggyMist")) {
        sessionManager.advanceTurn(nextTurn, "FoggyMist");
        if (currentHero.activeStatus?.includes("InvisiblePassage")) {
          sessionManager.clearCurrentHeroStatus("InvisiblePassage");
        }
      } else if (currentHero.activeStatus?.includes("InvisiblePassage")) {
        sessionManager.advanceTurn(nextTurn, "InvisiblePassage");
      } else {
        sessionManager.advanceTurn(nextTurn, null);
      }
    } else {
      sessionManager.advanceTurn(nextTurn, null);
    }
  }, [isMoving, gameSession, onNotify, mapInteractionLogic, sessionManager]);

  const attemptExitFromCurrentCell = useCallback(() => {
    const hero = gameSession?.heroes?.find(h => h.turnOrder === gameSession.currentTurn);
    if (!hero) return false;

    const mapCell = gameSession?.currentMap?.grid?.find(c => c.x === hero.x && c.y === hero.y);
    if (!mapCell || !cellAllowsMapExit(mapCell)) return false;

    if (!isMissionObjectiveCompleted) {
      if (pendingStairsExitConfirmedRef.current) {
        pendingStairsExitConfirmedRef.current = false;
      } else {
        const confirm = window.confirm("Vuoi ritirarti dalle scale senza completare la missione?");
        if (!confirm) {
          onNotify("Uscita annullata. Completa la missione o conferma la ritirata dalle scale.");
          return false;
        }
      }
    }

    sessionManager.markCurrentHeroEscaped();
    setTurnPhase(prev => ({ ...prev, IsTurnFinished: true }));

    if (isMissionObjectiveCompleted) {
      onNotify(`${hero.hero?.classe} è uscito dal dungeon!`);
    } else {
      onNotify(`${hero.hero?.classe} si ritira dalle scale.`);
    }

    endTurn(true);
    return true;
  }, [gameSession, isMissionObjectiveCompleted, sessionManager, onNotify, endTurn]);

  const forceTurnExhausted = useCallback((positionOverride) => {
    setMovementPoints(0);
    setHoveredPath([]);
    setHoveredPathVariant(null);
    setActivePath([]);
    setIsMoving(false);
    setIsMovingStarted(false);
    setTurnPhase(prev => ({ ...prev, HasMoved: true, HasPerformedAction: true }));
    
    const hero = gameSession?.heroes?.find(h => h.turnOrder === gameSession.currentTurn);
    const pos = positionOverride || (hero ? { x: hero.x, y: hero.y } : null);
    if (pos) {
      setCanOpenDoor(mapInteractionLogic?.isFrontOfDoor?.(pos.x, pos.y, null) || null);
    }
  }, [gameSession, mapInteractionLogic]);

  const computeMovementRoll = useCallback(
    (hero) => {
      if (!hero || hero.currentBody <= 0 || hero.isEscaped) return null;

      const stats = heroStatsLogic.calculateStats(hero);
      const bonusMoveDice = hero.bonusMovementDiceNextRoll || 0;
      const diceCount = Math.max(1, stats.movimento || 2) + bonusMoveDice;

      let roll = 0;
      for (let i = 0; i < diceCount; i++) {
        roll += Math.floor(Math.random() * 6) + 1;
      }

      return { roll, diceCount, bonusMoveDice, heroId: hero.heroId };
    },
    [heroStatsLogic]
  );

  const applyMovementRoll = useCallback(
    (hero) => {
      const result = computeMovementRoll(hero);
      if (!result) {
        setMovementPoints(null);
        return null;
      }

      setMovementPoints(result.roll);

      if (result.bonusMoveDice > 0) {
        sessionManager.clearBonusMovementDiceForHero(result.heroId);
        onNotify(
          `Movimento: ${result.roll} PM (${result.diceCount} dadi, +${result.bonusMoveDice} dalla pozione).`
        );
      }

      return result.roll;
    },
    [computeMovementRoll, sessionManager, onNotify]
  );

  /** @deprecated Tiro automatico a inizio turno; esposto per test e compatibilità. */
  const rollMovement = useCallback(() => {
    const hero = gameSession?.heroes?.find(
      (h) => h.turnOrder === gameSession.currentTurn
    );
    applyMovementRoll(hero);
  }, [gameSession, applyMovementRoll]);

  const handleBoardHover = useCallback((x, y) => {
    if (movementPoints == null || movementPoints <= 0 || isMoving) {
      setHoveredPath([]);
      setHoveredPathVariant(null);
      return;
    }

    const hero = gameSession?.heroes?.find(h => h.turnOrder === gameSession.currentTurn);
    if (!hero || hero.currentBody <= 0 || hero.isEscaped) {
      setHoveredPath([]);
      setHoveredPathVariant(null);
      return;
    }

    const path = hooksPathfinding.calculatePath(hero.x, hero.y, x, y, movementPoints, hero.heroId);
    if (path && path.length > 0) {
      let fullPath = [{ x: hero.x, y: hero.y }, ...path];
      fullPath = truncateHeroPathForMonsterObstacles(gameSession, fullPath, hero.heroId);
      if (fullPath.length < 2) {
        setHoveredPath([]);
        setHoveredPathVariant(null);
        return;
      }
      setHoveredPath(fullPath);

      let crossings = 0;
      for (let i = 1; i < fullPath.length; i++) {
        const oldVis = visibilityMap?.data?.find(c => c.x === fullPath[i - 1].x && c.y === fullPath[i - 1].y);
        const newVis = visibilityMap?.data?.find(c => c.x === fullPath[i].x && c.y === fullPath[i].y);
        const isDoor = gameSession?.currentMap?.porte?.some(p => p.x === fullPath[i].x && p.y === fullPath[i].y) || gameSession?.openedDoors?.includes(`${fullPath[i].x},${fullPath[i].y}`);
        
        if (oldVis?.valo !== newVis?.valo && !isDoor) {
          crossings++;
        }
      }

      if (hero.activeStatus?.includes("WallPass") && crossings > 1) {
        setHoveredPathVariant("blocked-by-second-wall");
      } else {
        setHoveredPathVariant("valid");
      }
    } else {
      setHoveredPath([]);
      setHoveredPathVariant(null);
    }
  }, [movementPoints, isMoving, gameSession, hooksPathfinding, visibilityMap]);

  const handleBoardClick = useCallback((x, y) => {
    if (isMoving || movementPoints == null || movementPoints <= 0) return;

    setIsMovingStarted(true);
    const hero = gameSession?.heroes?.find(h => h.turnOrder === gameSession.currentTurn);
    if (!hero || hero.currentBody <= 0 || hero.isEscaped) return;

    let path = hoveredPath;
    let pathVariant = hoveredPathVariant;

    if (!path || path.length === 0 || path[path.length - 1].x !== x || path[path.length - 1].y !== y) {
      const calcPath = hooksPathfinding.calculatePath(hero.x, hero.y, x, y, movementPoints, hero.heroId);
      if (calcPath && calcPath.length > 0) {
        path = [{ x: hero.x, y: hero.y }, ...calcPath];
        pathVariant = "valid";
      }
    }

    if (path && path.length > 1 && path[path.length - 1].x === x && path[path.length - 1].y === y) {
      const trunc = truncateHeroPathForMonsterObstacles(gameSession, path, hero.heroId);
      if (!trunc || trunc.length < 2) {
        onNotify("Il percorso è bloccato da un mostro.");
        setCanOpenDoor(mapInteractionLogic?.isFrontOfDoor?.(hero.x, hero.y, null) || null);
        return;
      }
      const pathToWalk = trunc;
      if (pathToWalk[pathToWalk.length - 1].x !== x || pathToWalk[pathToWalk.length - 1].y !== y) {
        onNotify("Movimento limitato: mostro lungo il percorso.");
      }
      let crossings = 0;
      for (let i = 1; i < pathToWalk.length; i++) {
        const oldVis = visibilityMap?.data?.find(c => c.x === pathToWalk[i - 1].x && c.y === pathToWalk[i - 1].y);
        const newVis = visibilityMap?.data?.find(c => c.x === pathToWalk[i].x && c.y === pathToWalk[i].y);
        const isDoor = gameSession?.currentMap?.porte?.some(p => p.x === pathToWalk[i].x && p.y === pathToWalk[i].y) || gameSession?.openedDoors?.includes(`${pathToWalk[i].x},${pathToWalk[i].y}`);

        if (oldVis?.valo !== newVis?.valo && !isDoor) {
          crossings++;
        }
      }
      const wallVariant = hero.activeStatus?.includes("WallPass") && crossings > 1 ? "blocked-by-second-wall" : "valid";
      if (wallVariant === "blocked-by-second-wall") {
        onNotify("Passapareti permette di attraversare un solo muro.");
        setCanOpenDoor(mapInteractionLogic?.isFrontOfDoor?.(hero.x, hero.y, null) || null);
        return;
      }
      setCanOpenDoor(null);
      setIsMoving(true);
      setActivePath([...pathToWalk]);
      setHoveredPath([]);
      setHoveredPathVariant(null);
    } else {
      // Click "muto": il pathfinding non ha trovato una route valida fino a (x, y).
      // Diagnostica la causa più probabile e mostra una notifica all'utente.
      // Senza questo feedback i sintomi tipici sono: "clicco sulla cella accanto
      // alla porta e non si muove; clicco una cella più lontana e attraversa".
      if (hero.x === x && hero.y === y) {
        // ignore: click on self
      } else {
        const targetCell = gameSession?.currentMap?.grid?.find(c => c.x === x && c.y === y);
        const otherHero = gameSession?.heroes?.find(h =>
          h.heroId !== hero.heroId && h.x === x && h.y === y && (h.currentBody || 0) > 0
        );
        const monsterAt = gameSession?.monsters?.find(m =>
          m.x === x && m.y === y && (m.currentBody || 0) > 0
        );
        if (otherHero) {
          onNotify("Non puoi terminare il movimento sulla cella di un alleato.");
        } else if (monsterAt) {
          onNotify("La cella è occupata da un mostro.");
        } else if (!targetCell) {
          onNotify("Cella fuori dalla mappa.");
        } else if (targetCell.arnt?.antroc === true) {
          onNotify("Quella è una cella muro: non è raggiungibile.");
        } else if (targetCell.mobili?.num != null || targetCell.arnt?.inv === true) {
          onNotify("La cella è ingombra di arredo.");
        } else {
          onNotify("Nessun percorso valido fino a quella cella con i punti movimento attuali.");
        }
      }
      setCanOpenDoor(mapInteractionLogic?.isFrontOfDoor?.(hero.x, hero.y, null) || null);
    }
  }, [isMoving, movementPoints, gameSession, hoveredPath, hoveredPathVariant, hooksPathfinding, onNotify, mapInteractionLogic]);

  const handleMonsterClick = useCallback((monsterId) => {
    const monster = gameSession?.monsters?.find(m => m.id === monsterId);
    const hero = gameSession?.heroes?.find(h => h.turnOrder === gameSession.currentTurn);
    if (!monster || !hero || hero.currentBody <= 0 || hero.isEscaped) return;

    const stats = heroStatsLogic.calculateStats(hero);
    const dx = Math.abs(hero.x - monster.x);
    const dy = Math.abs(hero.y - monster.y);
    const dist = dx + dy;

    let isValidTarget = false;
    if (dist <= 1 && canMeleeAcrossCells(hero.x, hero.y, monster.x, monster.y)) {
      isValidTarget = true;
    } else if (dx === 1 && dy === 1 && stats.canAttackDiagonal) {
      if (visibilityCalc?.hasLineOfSight(hero.x, hero.y, monster.x, monster.y)) isValidTarget = true;
    } else if (stats.canAttackRanged) {
      if (visibilityCalc?.hasLineOfSight(hero.x, hero.y, monster.x, monster.y)) isValidTarget = true;
    }

    if (isValidTarget && !isMoving && !turnPhase.HasPerformedAction) {
      const scriptRes = sessionManager.executeMissionScripts({
        baseSession: gameSession,
        eventType: 2,
        context: { monsterTypeId: monster.monster?.id, onDeath: false },
        visibilityMap
      });
      const attackBaseSession = scriptRes?.handled && scriptRes.session ? scriptRes.session : gameSession;
      // FIX: l'effetto `noatt`/`noattarma` finisce in `scriptRes.effects.attackBlocked`,
      // non al top-level. Senza questa correzione gli script non potevano mai
      // bloccare un attacco.
      if (scriptRes?.effects?.attackBlocked) return;

      const attackDice = heroStatsLogic.calculateAttackDice(hero, monster.monster);
      let defenseDice = monster.monster?.difesa || 0;

      if (monster.monster?.nome === "Gargoyle") {
        defenseDice += 2;
        onNotify("Il Gargoyle ha una difesa di pietra! (+2 dadi)");
      }
      if (monster.activeStatus?.includes("Tempest")) {
        defenseDice = 0;
        onNotify(`${monster.monster?.nome} è travolto dalla tempesta e non può difendersi!`);
      }

      const combatResult = combatLogic.resolveCombat(attackDice, defenseDice, false);
      const newBody = monster.currentBody - combatResult.damageDealt;
      const statusesToRemove = [];

      if (monster.activeStatus?.includes("Sleep") && newBody > 0) {
        statusesToRemove.push("Sleep");
        onNotify(`${monster.monster?.nome} si è svegliato!`);
      }
      if (monster.activeStatus?.includes("Tempest")) {
        statusesToRemove.push("Tempest");
      }

      setAttacksPerformed(prev => {
        const newCount = prev + 1;
        const canDouble = heroStatsLogic.canAttackTwice(hero, monster.monster);
        const quota = hero.bonusMeleeAttackQuota || 0;
        const baseCap = canDouble ? 2 : 1;
        const attackCap = quota > 0 ? Math.max(baseCap, quota) : baseCap;

        if (newCount < attackCap) {
          if (quota > 0 && newCount < quota) {
            onNotify("Puoi attaccare ancora (effetto della pozione).");
          } else if (canDouble && newCount < 2) {
            onNotify("Doppio attacco! Puoi attaccare ancora.");
          }
        } else {
          setTurnPhase(tp => ({ ...tp, HasPerformedAction: true }));
          if (quota > 0) {
            sessionManager.clearBonusMeleeAttackQuotaForHero(hero.heroId);
          }
        }
        return newCount;
      });

      if (isMovingStarted) {
        setTurnPhase(tp => ({ ...tp, HasMoved: true }));
      }

      setCanOpenDoor(mapInteractionLogic?.isFrontOfDoor?.(hero.x, hero.y, null) || null);

      const isRanged = dist > 1 || (dx === 1 && dy === 1 && !stats.canAttackDiagonal);
      let consumedId = null;
      if (isRanged) {
        consumedId = heroStatsLogic.getConsumableWeaponId(hero);
        if (consumedId) {
          onNotify("Hai lanciato l'arma e l'hai persa!");
        }
      }

      sessionManager.resolveHeroAttack(monsterId, combatResult, statusesToRemove, consumedId, attackBaseSession, isRanged);
    }
  }, [
    gameSession,
    isMoving,
    turnPhase.HasPerformedAction,
    heroStatsLogic,
    visibilityCalc,
    sessionManager,
    visibilityMap,
    combatLogic,
    onNotify,
    isMovingStarted,
    mapInteractionLogic,
    canMeleeAcrossCells
  ]);

  /** Per cursore hover: stesse condizioni geometriche/tempo dell’attacco melee (senza script noatt). */
  const canAttackMonsterAt = useCallback(
    (monsterId) => {
      const monster = gameSession?.monsters?.find((m) => m.id === monsterId);
      const hero = gameSession?.heroes?.find(
        (h) => h.turnOrder === gameSession.currentTurn
      );
      if (!monster || monster.currentBody <= 0 || !hero || hero.currentBody <= 0 || hero.isEscaped) {
        return false;
      }
      if (isMoving || turnPhase.HasPerformedAction) return false;

      const stats = heroStatsLogic.calculateStats(hero);
      const dx = Math.abs(hero.x - monster.x);
      const dy = Math.abs(hero.y - monster.y);
      const dist = dx + dy;

      let isValidTarget = false;
      if (dist <= 1 && canMeleeAcrossCells(hero.x, hero.y, monster.x, monster.y)) {
        isValidTarget = true;
      } else if (dx === 1 && dy === 1 && stats.canAttackDiagonal) {
        if (visibilityCalc?.hasLineOfSight(hero.x, hero.y, monster.x, monster.y)) {
          isValidTarget = true;
        }
      } else if (stats.canAttackRanged) {
        if (visibilityCalc?.hasLineOfSight(hero.x, hero.y, monster.x, monster.y)) {
          isValidTarget = true;
        }
      }
      if (!isValidTarget) return false;

      const canDouble = heroStatsLogic.canAttackTwice(hero, monster.monster);
      const quota = hero.bonusMeleeAttackQuota || 0;
      const baseCap = canDouble ? 2 : 1;
      const attackCap = quota > 0 ? Math.max(baseCap, quota) : baseCap;
      if (attacksPerformed >= attackCap) return false;

      return true;
    },
    [
      gameSession,
      isMoving,
      turnPhase.HasPerformedAction,
      heroStatsLogic,
      visibilityCalc,
      canMeleeAcrossCells,
      attacksPerformed
    ]
  );

  const handleOpenDoor = useCallback(() => {
    if (canOpenDoor) {
      mapInteractionLogic?.openPassage?.(canOpenDoor.passageCell.x, canOpenDoor.passageCell.y, canOpenDoor.destination.x, canOpenDoor.destination.y);
      const hero = gameSession?.heroes?.find(h => h.turnOrder === gameSession.currentTurn);
      if (hero) {
        setCanOpenDoor(mapInteractionLogic?.isFrontOfDoor?.(hero.x, hero.y, null) || null);
      }
    }
  }, [canOpenDoor, mapInteractionLogic, gameSession]);

  const markActionDone = useCallback(() => {
    setTurnPhase(prev => ({ ...prev, HasPerformedAction: true, HasMoved: isMovingStarted ? true : prev.HasMoved }));
    const hero = gameSession?.heroes?.find(h => h.turnOrder === gameSession.currentTurn);
    if (hero) {
      setCanOpenDoor(mapInteractionLogic?.isFrontOfDoor?.(hero.x, hero.y, null) || null);
    }
  }, [isMovingStarted, gameSession, mapInteractionLogic]);

  useEffect(() => {
    if (!gameSession) return;
    const hero = gameSession.heroes?.find(h => h.turnOrder === gameSession.currentTurn);
    if (!hero) return;

    if (turnPhase.HasPerformedAction) {
      setCanAttack(false);
    } else {
      const stats = heroStatsLogic.calculateStats(hero);
      let attackPossible = false;
      for (const monster of gameSession.monsters || []) {
        const dx = Math.abs(hero.x - monster.x);
        const dy = Math.abs(hero.y - monster.y);
        const dist = dx + dy;

        if (dist <= 1 && canMeleeAcrossCells(hero.x, hero.y, monster.x, monster.y)) {
          attackPossible = true;
          break;
        } else if (dx === 1 && dy === 1 && stats.canAttackDiagonal) {
          if (visibilityCalc?.hasLineOfSight(hero.x, hero.y, monster.x, monster.y)) {
            attackPossible = true;
            break;
          }
        } else if (stats.canAttackRanged) {
          if (visibilityCalc?.hasLineOfSight(hero.x, hero.y, monster.x, monster.y)) {
            attackPossible = true;
            break;
          }
        }
      }
      setCanAttack(attackPossible);
    }

    const visibleMonsters = gameSession.monsters?.filter(m => {
      const cell = visibilityMap?.data?.find(c => c.x === m.x && c.y === m.y);
      return cell && !cell.fog;
    }) || [];

    if (visibleMonsters.length === 0) {
      const courageRemoved = gameSession.heroes?.some(h => h.activeStatus?.includes("Courage"));
      if (courageRemoved) {
        onNotify("L'effetto di Coraggio svanisce: non ci sono più mostri in vista.");
        sessionManager.clearHeroStatusEverywhere("Courage");
      }
    }
  }, [gameSession, turnPhase.HasPerformedAction, heroStatsLogic, visibilityCalc, visibilityMap, onNotify, sessionManager, canMeleeAcrossCells]);

  useEffect(() => {
    const currentHero = gameSession?.heroes?.find(h => h.turnOrder === gameSession?.currentTurn);
    const activeTurnKey = `${gameSession?.currentTurn}-${currentHero?.heroId}`;

    if (previousActiveTurnKey.current !== activeTurnKey) {
      pendingStairsExitConfirmedRef.current = false;
      setTurnPhase({ HasMoved: false, HasPerformedAction: false, IsTurnFinished: false });
      setAttacksPerformed(0);
      setIsMoving(false);
      setIsMovingStarted(false);
      setActivePath([]);
      setHoveredPath([]);
      setHoveredPathVariant(null);

      if (currentHero) {
        setCanOpenDoor(
          mapInteractionLogic?.isFrontOfDoor?.(currentHero.x, currentHero.y, null) || null
        );
        applyMovementRoll(currentHero);
      } else {
        setMovementPoints(null);
      }

      previousActiveTurnKey.current = activeTurnKey;
    }
  }, [
    gameSession?.currentTurn,
    gameSession?.heroes,
    mapInteractionLogic,
    applyMovementRoll,
  ]);

  useEffect(() => {
    if (activePath.length < 2) {
      if (isMoving) {
        setIsMoving(false);
        setActivePath([]);
      }
      const exited = attemptExitFromCurrentCell();
      if (exited) return;
      
      const hero = gameSession?.heroes?.find(h => h.turnOrder === gameSession.currentTurn);
      if (hero) {
        setCanOpenDoor(mapInteractionLogic?.isFrontOfDoor?.(hero.x, hero.y, null) || null);
      }
      
      if (movementPoints !== null && movementPoints <= 0) {
        setTurnPhase(prev => ({ ...prev, HasMoved: true }));
      }
      return;
    }

    const timer = setTimeout(() => {
      const nextPos = activePath[1];
      const oldPos = activePath[0];

      const destCellForExit = gameSession?.currentMap?.grid?.find(
        (c) => c.x === nextPos.x && c.y === nextPos.y
      );
      if (
        destCellForExit &&
        cellAllowsMapExit(destCellForExit) &&
        !isMissionObjectiveCompleted
      ) {
        if (!pendingStairsExitConfirmedRef.current) {
          const ok = window.confirm(
            "Vuoi ritirarti dalle scale senza completare la missione?"
          );
          if (!ok) {
            onNotify(
              "Uscita annullata. Completa la missione o conferma la ritirata dalle scale."
            );
            setActivePath([{ x: oldPos.x, y: oldPos.y }]);
            setIsMoving(false);
            return;
          }
          pendingStairsExitConfirmedRef.current = true;
        }
      }

      const heroForStep = gameSession?.heroes?.find(h => h.turnOrder === gameSession.currentTurn);
      if (
        heroForStep &&
        gameSession?.monsters?.some(
          (m) =>
            m.x === nextPos.x &&
            m.y === nextPos.y &&
            (m.currentBody || 0) > 0
        )
      ) {
        onNotify("Movimento interrotto: la casella è occupata da un mostro.");
        setActivePath([{ x: oldPos.x, y: oldPos.y }]);
        setIsMoving(false);
        return;
      }

      setMovementPoints(prev => (prev !== null ? prev - 1 : 0));
      
      const oldVis = visibilityMap?.data?.find(c => c.x === oldPos.x && c.y === oldPos.y);
      const newVis = visibilityMap?.data?.find(c => c.x === nextPos.x && c.y === nextPos.y);
      const isDoor = gameSession?.currentMap?.porte?.some(p => p.x === nextPos.x && p.y === nextPos.y) || gameSession?.openedDoors?.includes(`${nextPos.x},${nextPos.y}`);
      
      if (oldVis?.valo !== newVis?.valo && !isDoor) {
        const hero = gameSession?.heroes?.find(h => h.turnOrder === gameSession.currentTurn);
        if (hero?.activeStatus?.includes("WallPass")) {
          sessionManager.clearCurrentHeroStatus("WallPass");
        }
      }

      const trap = gameSession?.currentMap?.grid?.find(c => c.x === nextPos.x && c.y === nextPos.y)?.trpl;
      if (trap && trap.tipo > 0 && trapsLogic?.checkTrapActivation?.(trap, nextPos.x, nextPos.y)) {
        sessionManager.resolveMovementTrap(nextPos.x, nextPos.y, trap.tipo, trap.rccadex, trap.rccadey);
        trapsLogic?.registerTriggeredTrap?.(nextPos.x, nextPos.y, trap.tipo);
        onNotify("Hai fatto scattare una trappola!");
        // Regola HQ: dopo aver fatto scattare una trappola in movimento, l'eroe
        // perde anche il resto del movimento residuo.
        setActivePath([]);
        setMovementPoints(0);
        setTurnPhase(prev => ({ ...prev, HasMoved: true }));
        return;
      }

      sessionManager.moveCurrentHeroTo(nextPos.x, nextPos.y, gameSession);

      const roomChanged = oldVis?.valo !== newVis?.valo;
      // L'eroe è già "logicamente" nella nuova cella anche se la sessione React
      // non ha ancora propagato il cambio. Passiamo quindi un context esplicito
      // con coordinate aggiornate per poter risolvere correttamente
      // `sestanza`/`getRoomIdFromVisibilityMap` lato runtime.
      const newRoomId = newVis?.valo != null ? String(newVis.valo) : null;
      const oldRoomId = oldVis?.valo != null ? String(oldVis.valo) : null;
      const moveContext = {
        previousPosition: { x: oldPos.x, y: oldPos.y },
        newPosition: { x: nextPos.x, y: nextPos.y },
        roomId: newRoomId,
        previousRoomId: oldRoomId,
      };

      // FIX bug "PM scalano ma eroe non si muove" attraversando una porta con
      // uno script di evento 1/8 attivo. Causa: il commit della session dello
      // script in `executeMissionScripts` è un setter (non updater), quindi se
      // passassimo `gameSession` (eroe ancora sulla cella precedente) il
      // commit dello script schiaccerebbe il `moveCurrentHeroTo` appena
      // queueato. Calcoliamo localmente la session "post-step" così il
      // runtime vede già l'eroe nella nuova cella e il commit finale contiene
      // sia il movimento sia gli effetti dello script.
      let movedSession = moveCurrentHeroInSession(gameSession, nextPos.x, nextPos.y);
      movedSession = mergeOpenedDoorsAfterStep(movedSession, oldPos.x, oldPos.y, nextPos.x, nextPos.y);

      const scriptRes1 = sessionManager.executeMissionScripts({
        baseSession: movedSession,
        eventType: 1,
        context: moveContext,
        visibilityMap,
      });
      let scriptRes8 = null;
      if (roomChanged) {
        scriptRes8 = sessionManager.executeMissionScripts({
          baseSession: scriptRes1?.session || movedSession,
          eventType: 8,
          context: moveContext,
          visibilityMap,
        });
      }

      const finalRes = scriptRes8 || scriptRes1;
      // FIX: tutti gli effetti runtime sono dentro `finalRes.effects.*`. La
      // versione precedente li leggeva al top-level e quindi i comandi
      // `pospsg` (movementDelta), `fineturno` (forceFinishTurn) ed eventuali
      // arresti sintetici non avevano alcun effetto sul flusso del turno.
      const fxEffects = finalRes?.effects;
      if (fxEffects) {
        if (fxEffects.movementDelta) {
          setMovementPoints(prev => (prev !== null ? prev + fxEffects.movementDelta : prev));
        }
        if (fxEffects.stopMovement) {
          setActivePath([]);
          setMovementPoints(0);
        }
        if (fxEffects.forceFinishTurn) {
          forceTurnExhausted();
        }
      }

      if (!fxEffects?.stopMovement && !fxEffects?.forceFinishTurn) {
        setActivePath(prev => prev.slice(1));
      }
      
      const hero = gameSession?.heroes?.find(h => h.turnOrder === gameSession.currentTurn);
      if (hero) {
        setCanOpenDoor(mapInteractionLogic?.isFrontOfDoor?.(nextPos.x, nextPos.y, null) || null);
      }

    }, 300);

    return () => clearTimeout(timer);
  }, [
    activePath,
    isMoving,
    movementPoints,
    gameSession,
    visibilityMap,
    trapsLogic,
    sessionManager,
    mapInteractionLogic,
    attemptExitFromCurrentCell,
    forceTurnExhausted,
    isMissionObjectiveCompleted,
    onNotify,
  ]);

  return {
    turnPhase,
    movementPoints,
    hoveredPath,
    hoveredPathVariant,
    isMoving,
    canOpenDoor,
    handleOpenDoor,
    rollMovement,
    handleBoardHover,
    handleBoardClick,
    handleMonsterClick,
    canAttackMonsterAt,
    markActionDone,
    forceTurnExhausted,
    endTurn,
    isMissionObjectiveCompleted,
    canAttack
  };
}